#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Sets up ONE environment (dev or production) end to end — see
# docs/setup/environments.md for the target shape. Run it for dev first:
#
#   bash docs/setup/environments.sh dev
#   bash docs/setup/environments.sh production
#   bash docs/setup/environments.sh dev --from 13     # resume at a stage
#
# Captured values: .env.<env>.setup.local (repo root, git-ignored).
# Paste-ready per-app files: .env.<env>.web.local / .env.<env>.admin.local.
# The repo root is deliberate: Next.js only loads env files from each app's
# own folder, so these can never leak into a local build.

TOTAL_STAGES=18

REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || { printf 'Run this from inside the repo checkout.\n'; exit 1; }
cd "$REPO_ROOT"

TARGET="${1:-}"
FROM=1
[[ "${2:-}" == "--from" ]] && FROM="${3:-1}"
[[ "$FROM" =~ ^[0-9]+$ ]] || FROM=1
case "$TARGET" in
  dev|production) ;;
  *) printf 'Usage: bash docs/setup/environments.sh dev|production [--from N]\n'; exit 1 ;;
esac

SHORT=dev; [[ "$TARGET" == production ]] && SHORT=prod
ENV_FILE=".env.${TARGET}.setup.local"
WEB_OUT=".env.${TARGET}.web.local"
ADMIN_OUT=".env.${TARGET}.admin.local"
REMOTE_URL=$(git remote get-url origin 2>/dev/null || echo "")
REPO="${REMOTE_URL#*github.com[:/]}"; REPO="${REPO%.git}"

# ── helpers (author-side; the library above stays untouched) ──────────────

is_dev() { [[ "$TARGET" == dev ]]; }
has_gh() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# load_all — bring every value saved on an earlier run into the shell, so a
# --from resume (or a later stage) can use values captured before.
load_all() {
  [[ -f "$ENV_FILE" ]] || return 0
  local line
  while IFS= read -r line || [[ -n "$line" ]]; do
    [[ "$line" =~ ^[A-Z_][A-Z0-9_]*= ]] || continue
    printf -v "${line%%=*}" '%s' "${line#*=}"
  done < "$ENV_FILE"
}

gen_secret() {
  if command -v openssl >/dev/null 2>&1; then openssl rand -hex 32
  else od -An -tx1 -N32 /dev/urandom | tr -d ' \n'; fi
}

# ensure_generated KEY — generate a random hex secret once; keep it on re-runs.
ensure_generated() {
  local key="$1"
  if [[ -z "${!key:-}" ]]; then
    printf -v "$key" '%s' "$(gen_secret)"
    write_env "$key" "${!key}"
  else
    note "$key already generated — keeping it."
  fi
}

# ask_req KEY "Prompt" [secret] — ask until a value is given.
ask_req() {
  local key="$1" prompt="$2" kind="${3:-}"
  while :; do
    if [[ "$kind" == secret ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    [[ -n "${!key}" ]] && break
    warn "This one is required."
  done
}

# ask_url KEY "Prompt" — a required URL, trailing slash trimmed, saved.
ask_url() {
  local key="$1" prompt="$2" v
  ask_req "$key" "$prompt"
  v="${!key}"; v="${v%/}"
  [[ "$v" == https://* ]] || warn "That doesn't start with https:// — double-check it."
  printf -v "$key" '%s' "$v"
  write_env "$key" "$v"
}

# ref_of https://<ref>.supabase.co → <ref> (or "_", the dashboard's project picker).
ref_of() {
  local r="${1#https://}"; r="${r%%.*}"
  printf '%s' "${r:-_}"
}

# set_env_secret NAME VALUE ENV — a GitHub *Environment* secret (db-migrate
# reads DIRECT_URL per environment). Returns non-zero when gh isn't ready.
set_env_secret() {
  local name="$1" value="$2" env="$3"
  has_gh || return 1
  if printf '%s' "$value" | gh secret set "$name" --env "$env" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name@$env")
    printf '  %s✓ set%s GitHub secret %s (environment %s)\n' "$GREEN" "$RESET" "$name" "$env"
    return 0
  fi
  return 1
}

# run_cmd "description" command... — run a repo script; a failure is
# reported and listed at the end instead of aborting the wizard.
run_cmd() {
  local desc="$1"; shift
  printf '  %s$ %s%s\n' "$DIM" "$desc" "$RESET"
  if "$@"; then
    printf '  %s✓ done%s\n' "$GREEN" "$RESET"
  else
    warn "That failed. Fix it, then re-run with --from $_STAGE_INDEX."
    SKIPPED+=("Stage $_STAGE_INDEX: $desc")
  fi
}

prisma_db() { (cd packages/database && DIRECT_URL="${DIRECT_URL:-}" npx --no-install prisma "$@"); }

show_sql() {
  local file="$1" title="$2"
  say "$title"
  if [[ -f "$file" ]]; then
    printf '%s────────── %s ──────────%s\n' "$DIM" "$file" "$RESET"
    cat "$file"
    printf '%s────────────────────────────────────────%s\n' "$DIM" "$RESET"
  else
    warn "Couldn't find $file — run the wizard from the repo checkout."
  fi
}

open_local() {
  if command -v notepad.exe >/dev/null 2>&1; then
    (notepad.exe "$1" >/dev/null 2>&1 &)
    printf '  %s↗ opened%s %s in Notepad\n' "$GREEN" "$RESET" "$1"
  else
    note "Open $1 in your editor to copy it."
  fi
}

# The runtime DATABASE_URL: Supabase's transaction-pooler URI, rewritten to
# the least-privilege app_runtime login (app_runtime_role.sql).
build_runtime_url() {
  local uri="$1" rest userinfo hostpart user
  rest="${uri#*://}"; userinfo="${rest%%@*}"; hostpart="${rest#*@}"; hostpart="${hostpart%%\?*}"
  user="${userinfo%%:*}"
  # uselibpqcompat: node-postgres treats a bare sslmode=require as verify-full,
  # which rejects the pooler's certificate (Supabase's own CA); with it,
  # require means what it does in libpq: encrypted, server not verified.
  printf 'postgresql://app_runtime.%s:%s@%s?pgbouncer=true&uselibpqcompat=true&sslmode=require' \
    "${user#postgres.}" "$APP_RUNTIME_PASSWORD" "$hostpart"
}

emit() {
  local file="$1" key="$2" value="${3:-}"
  [[ -n "$value" ]] && printf '%s=%s\n' "$key" "$value" >> "$file"
  return 0
}

WEB_KEYS=(NEXT_PUBLIC_SUPABASE_URL NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY SUPABASE_SERVICE_ROLE_KEY
  DATABASE_URL NEXT_PUBLIC_RAZORPAY_KEY_ID RAZORPAY_KEY_ID RAZORPAY_KEY_SECRET RAZORPAY_WEBHOOK_SECRET
  RESEND_API_KEY EMAIL_FROM UPSTASH_REDIS_REST_URL UPSTASH_REDIS_REST_TOKEN CACHE_STORE CACHE_NAMESPACE
  DEPLOY_ENV STOREFRONT_REVALIDATE_SECRET NEXT_PUBLIC_STOREFRONT_URL WHATSAPP_NUMBER)
ADMIN_KEYS=(NEXT_PUBLIC_AUTH_SUPABASE_URL NEXT_PUBLIC_AUTH_SUPABASE_PUBLISHABLE_KEY AUTH_SUPABASE_SERVICE_ROLE_KEY
  NEXT_PUBLIC_SUPABASE_URL NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY SUPABASE_SERVICE_ROLE_KEY DATABASE_URL
  RESEND_API_KEY EMAIL_FROM NEXT_PUBLIC_STOREFRONT_URL NEXT_PUBLIC_ADMIN_URL STOREFRONT_REVALIDATE_SECRET
  CACHE_STORE CACHE_NAMESPACE UPSTASH_REDIS_REST_URL UPSTASH_REDIS_REST_TOKEN)

write_app_files() {
  # Derived values: the browser key id is the same as the server one; the
  # deployment label and Redis cache only apply on Hostinger (production).
  NEXT_PUBLIC_RAZORPAY_KEY_ID="${RAZORPAY_KEY_ID:-}"
  if is_dev; then DEPLOY_ENV=""; CACHE_STORE=""; CACHE_NAMESPACE=""
  else DEPLOY_ENV="production"; fi

  local key
  printf '# %s — apps/web. Generated by docs/setup/environments.sh; re-run it to regenerate.\n' "$TARGET" > "$WEB_OUT"
  for key in "${WEB_KEYS[@]}"; do emit "$WEB_OUT" "$key" "${!key:-}"; done
  printf '# %s — apps/admin. Generated by docs/setup/environments.sh; re-run it to regenerate.\n' "$TARGET" > "$ADMIN_OUT"
  for key in "${ADMIN_KEYS[@]}"; do emit "$ADMIN_OUT" "$key" "${!key:-}"; done
  printf '  %s✓ wrote%s %s and %s\n' "$GREEN" "$RESET" "$WEB_OUT" "$ADMIN_OUT"

  local missing=() k
  for k in NEXT_PUBLIC_SUPABASE_URL NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY SUPABASE_SERVICE_ROLE_KEY DATABASE_URL \
           NEXT_PUBLIC_AUTH_SUPABASE_URL NEXT_PUBLIC_AUTH_SUPABASE_PUBLISHABLE_KEY AUTH_SUPABASE_SERVICE_ROLE_KEY \
           RESEND_API_KEY EMAIL_FROM NEXT_PUBLIC_STOREFRONT_URL NEXT_PUBLIC_ADMIN_URL STOREFRONT_REVALIDATE_SECRET; do
    [[ -n "${!k:-}" ]] || missing+=("$k")
  done
  if ! is_dev; then
    for k in UPSTASH_REDIS_REST_URL UPSTASH_REDIS_REST_TOKEN; do [[ -n "${!k:-}" ]] || missing+=("$k"); done
  fi
  if (( ${#missing[@]} )); then
    warn "Still empty (the apps refuse to boot or lose features without them): ${missing[*]}"
    SKIPPED+=("Fill in: ${missing[*]} (re-run the stage that asks for it)")
  fi
}

# ── 1 ────────────────────────────────────────────────────────────────────
s1() {
  stage "Before you start"
  say "Setting up the ${BOLD}${TARGET}${RESET} environment. Be signed in to:"
  step "GitHub (admin on $REPO), Supabase, Resend, Razorpay, Upstash"
  if is_dev; then
    step "Vercel (it hosts dev)"
  else
    step "Hostinger — sign in with the client's login yourself, in the browser."
    note "  This wizard never asks for any password."
  fi
  step "Your domain's DNS (hPanel → Domains → DNS, if it's registered at Hostinger)"
  printf '\n'
  say "Values you paste are saved to $ENV_FILE; stage 15 writes"
  say "$WEB_OUT and $ADMIN_OUT for the hosting dashboards."
  note "All git-ignored. Back them up in a password manager — the generated secrets live nowhere else."
  note "Resume later with: bash docs/setup/environments.sh $TARGET --from <stage>"
  printf '\n'
  local t
  for t in git node npm openssl; do command -v "$t" >/dev/null 2>&1 || warn "$t not found on PATH."; done
  [[ -d node_modules ]] || warn "Run npm install first — later stages run the repo's own scripts."
  if has_gh; then
    note "gh is signed in, so GitHub secrets are set for you."
  else
    warn "GitHub CLI (gh) isn't installed or signed in — GitHub secrets become browser steps."
    note "  Optional: winget install GitHub.cli, then gh auth login, then re-run."
  fi
  if ! git check-ignore -q "$ENV_FILE" || ! git check-ignore -q "$WEB_OUT"; then
    warn "$ENV_FILE isn't git-ignored — stopping so no secret can be committed."
    exit 1
  fi
  pause
}

# ── 2 ────────────────────────────────────────────────────────────────────
s2() {
  stage "GitHub — the dev branch and the '$TARGET' environment"
  git fetch -q origin 2>/dev/null || warn "git fetch failed — check your connection to GitHub."
  if git ls-remote --exit-code --heads origin dev >/dev/null 2>&1; then
    note "Branch dev already exists on GitHub."
  else
    say "Dev deploys from a branch called dev, which isn't on GitHub yet."
    if confirm "Create it on GitHub from origin/main? (Your local branch and files aren't touched.)"; then
      run_cmd "git push origin origin/main → dev" git push origin refs/remotes/origin/main:refs/heads/dev
    else
      SKIPPED+=("Create the dev branch on GitHub from main")
    fi
  fi
  printf '\n'
  say "Now the GitHub Environment the db-migrate workflow uses for this database:"
  open_url "https://github.com/$REPO/settings/environments/new"
  step "Name: $TARGET (exactly) → Configure environment."
  if is_dev; then
    step "Deployment branches: leave 'No restriction'."
  else
    step "Tick 'Required reviewers' and add yourself (and the client, if they should approve)."
    note "  If GitHub says that needs a paid plan on a private repo, skip the tick."
    step "Deployment branches → 'Selected branches and tags' → add main and dev."
    note "  dev, so you can migrate production from the branch you're about to merge."
    step "Save protection rules."
    printf '\n'
    step "Recommended: Settings → Branches → add a rule for main: require a pull request before merging."
  fi
  note "This environment's DIRECT_URL secret is added in stage 5."
  pause "Environment '$TARGET' saved?"
}

# ── 3 ────────────────────────────────────────────────────────────────────
s3_dev() {
  stage "Vercel — create the two dev projects"
  say "Dev runs as Vercel *Preview* deployments of the dev branch. Vercel's own"
  say "Production environment stays empty — production lives on Hostinger."
  open_url "https://vercel.com/new"
  step "Import $REPO. Name it e.g. storefront-web-dev. Root Directory: apps/web."
  step "Framework Next.js, no env vars yet → Deploy. That first build is of main; ignore whatever it does."
  step "Then in the project's Settings (labels may differ slightly):"
  step "  Build and Deployment → Node.js Version 22 · 'Include files outside the root directory' on"
  step "  Build and Deployment (older UI: Git) → Ignored Build Step → Custom command:"
  printf '\n      %sif [ "$VERCEL_GIT_COMMIT_REF" = "main" ]; then exit 0; else exit 1; fi%s\n' "$BOLD" "$RESET"
  note "      (skips main, which Hostinger builds; builds dev)"
  step "  Functions → Region: Mumbai (bom1)"
  step "  Deployment Protection → keep Vercel Authentication on (dev isn't public) →"
  step "  'Protection Bypass for Automation' → create a secret, copy it."
  ask_secret VERCEL_AUTOMATION_BYPASS_SECRET_WEB "web bypass secret (Enter skips if protection is off):"
  write_env VERCEL_AUTOMATION_BYPASS_SECRET_WEB "$VERCEL_AUTOMATION_BYPASS_SECRET_WEB"
  printf '\n'
  step "Repeat for the back office: storefront-admin-dev, Root Directory apps/admin, same settings."
  ask_secret VERCEL_AUTOMATION_BYPASS_SECRET_ADMIN "admin bypass secret (Enter skips):"
  write_env VERCEL_AUTOMATION_BYPASS_SECRET_ADMIN "$VERCEL_AUTOMATION_BYPASS_SECRET_ADMIN"
  pause "Both projects created?"
  _clear
  say "Dev addresses — they're baked into the build, so decide them now. Either:"
  step "a custom domain per project: Settings → Domains → Add, e.g. dev.<domain> /"
  step "  admin-dev.<domain>, assigned to Git branch dev; add the CNAME it shows to your DNS; or"
  step "Vercel's branch URL: https://<project>-git-dev-<team>.vercel.app"
  note "  (<team> is in your dashboard's URL; very long names get shortened — check after the first dev deploy)"
  ask_url NEXT_PUBLIC_STOREFRONT_URL "Dev storefront URL:"
  ask_url NEXT_PUBLIC_ADMIN_URL "Dev admin URL:"
}

s3_prod() {
  stage "Your domain"
  say "Production is www.<domain> (storefront) and admin.<domain> (back office), on Hostinger."
  ask_req DOMAIN "Domain, without www (e.g. example.in):"
  DOMAIN="${DOMAIN#https://}"; DOMAIN="${DOMAIN#http://}"; DOMAIN="${DOMAIN#www.}"; DOMAIN="${DOMAIN%/}"
  write_env DOMAIN "$DOMAIN"
  NEXT_PUBLIC_STOREFRONT_URL="https://www.$DOMAIN"; write_env NEXT_PUBLIC_STOREFRONT_URL "$NEXT_PUBLIC_STOREFRONT_URL"
  NEXT_PUBLIC_ADMIN_URL="https://admin.$DOMAIN";    write_env NEXT_PUBLIC_ADMIN_URL "$NEXT_PUBLIC_ADMIN_URL"
  note "The Hostinger websites come in stage 16, once every value exists — they need their env vars before the first build."
  pause
}

s3() { if is_dev; then s3_dev; else s3_prod; fi; }

# ── 4 ────────────────────────────────────────────────────────────────────
s4() {
  stage "Storefront Supabase — create the project"
  say "Holds the shop's Postgres, customer sign-in and file storage."
  if is_dev; then
    note "Already have the storefront project you've been building against? Reuse it as dev — just copy its keys."
  else
    warn "Put this project's organisation on the Pro plan: Free projects pause after a week idle (= site down) and have no daily backups."
  fi
  open_url "https://supabase.com/dashboard/new"
  step "Name: storefront-$SHORT · Region: South Asia (Mumbai)"
  step "Database password: a strong one, saved in your password manager — stage 5 needs it."
  pause "Project ready?"
  say "Its keys: Project Settings → API Keys (Project URL is under Data API, or the Connect button)."
  open_url "https://supabase.com/dashboard/project/_/settings/api-keys"
  ask_url NEXT_PUBLIC_SUPABASE_URL "Project URL (https://<ref>.supabase.co):"
  ask_req NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "Publishable (or legacy anon) key:"
  ask_req SUPABASE_SERVICE_ROLE_KEY "Secret / service_role key (hidden):" secret
  write_env NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"
  write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
  warn "The secret key bypasses Row-Level Security: server-only, never in a NEXT_PUBLIC_ variable."
  pause
}

# ── 5 ────────────────────────────────────────────────────────────────────
s5() {
  stage "Storefront Supabase — apply the database migrations"
  local ref; ref=$(ref_of "${NEXT_PUBLIC_SUPABASE_URL:-}")
  say "Migrations use the postgres login on port 5432 (never the app's pooled URL)."
  open_url "https://supabase.com/dashboard/project/$ref?showConnect=true"
  step "Connect → Connection string → Method: Session pooler → copy the URI."
  step "Replace [YOUR-PASSWORD] with the database password from stage 4."
  ask_req DIRECT_URL "Session pooler URI (hidden):" secret
  [[ "$DIRECT_URL" == *"[YOUR-PASSWORD]"* ]] && warn "It still says [YOUR-PASSWORD] — re-run --from 5 with the real password."
  [[ "$DIRECT_URL" == *":5432/"* ]] || warn "Expected port 5432. The 6543 transaction pooler can't run migrations."
  write_env DIRECT_URL "$DIRECT_URL"
  if ! set_env_secret DIRECT_URL "$DIRECT_URL" "$TARGET"; then
    open_url "https://github.com/$REPO/settings/environments"
    step "Open '$TARGET' → Environment secrets → Add secret: name DIRECT_URL, value = that same URI."
    pause "Secret added?"
  fi
  printf '\n'

  local dirty; dirty=$(git status --porcelain -- packages/database/prisma/migrations)
  if ! is_dev; then
    local head origin
    head=$(git rev-parse HEAD); origin=$(git rev-parse refs/remotes/origin/main 2>/dev/null || echo none)
    if [[ -n "$dirty" || "$head" != "$origin" ]]; then
      warn "This checkout isn't exactly origin/main (uncommitted or unpushed migrations)."
      warn "Production only ever gets migrations committed on main, so they won't run from here."
      step "Instead: GitHub → Actions → db-migrate → Run workflow → production."
      SKIPPED+=("Migrate production: Actions → db-migrate → production")
      pause; return
    fi
  elif [[ -n "$dirty" ]]; then
    warn "These uncommitted migrations in this checkout will be applied to dev as well:"
    printf '%s\n' "$dirty" | sed 's/^/      /'
  fi
  say "Pending migrations:"
  prisma_db migrate status || true
  if confirm "Apply them to storefront-$SHORT now? (migrate deploy — never resets data)"; then
    run_cmd "prisma migrate deploy" prisma_db migrate deploy
  else
    SKIPPED+=("Migrate storefront-$SHORT (re-run --from 5, or Actions → db-migrate → $TARGET)")
  fi
  pause
}

# ── 6 ────────────────────────────────────────────────────────────────────
s6() {
  stage "Storefront Supabase — security SQL and the apps' database login"
  local ref; ref=$(ref_of "${NEXT_PUBLIC_SUPABASE_URL:-}")
  say "Three SQL files, each run once in this project's SQL editor (paste → Run)."
  open_url "https://supabase.com/dashboard/project/$ref/sql/new"
  show_sql packages/database/prisma/sql/sync_user.sql "1/3 · copies each new sign-up into public.users, plus the starter RLS policies:"
  pause "Ran with no errors? Enter for the next one"
  _clear
  show_sql packages/database/prisma/sql/auto_enable_rls.sql "2/3 · turns RLS on for every future table:"
  pause "Ran with no errors? Enter for the next one"
  _clear
  ensure_generated APP_RUNTIME_PASSWORD
  say "3/3 · the least-privilege login the apps run as. Its password is already filled in:"
  printf '%s──────────%s\n' "$DIM" "$RESET"
  sed "s/CHANGE_ME/$APP_RUNTIME_PASSWORD/" packages/database/prisma/sql/app_runtime_role.sql
  printf '%s──────────%s\n' "$DIM" "$RESET"
  note "Ran it on this project before? Then run only: alter role app_runtime password '<the password above>';"
  pause "Ran with no errors?"
  _clear
  say "Now the apps' runtime connection (transaction pooler, port 6543):"
  open_url "https://supabase.com/dashboard/project/$ref?showConnect=true"
  step "Connect → Method: Transaction pooler → copy the URI. Leave [YOUR-PASSWORD] as it is."
  ask_req POOLER_URI "Transaction pooler URI:"
  write_env POOLER_URI "$POOLER_URI"
  local user="${POOLER_URI#*://}"; user="${user%%:*}"
  [[ "$user" == postgres.* ]] || warn "Expected a pooler URI whose user is postgres.<ref> — check you copied the pooler one."
  [[ "$POOLER_URI" == *":6543/"* ]] || warn "Expected port 6543."
  DATABASE_URL=$(build_runtime_url "$POOLER_URI")
  write_env DATABASE_URL "$DATABASE_URL"
  note "DATABASE_URL = app_runtime on port 6543 with pgbouncer=true&uselibpqcompat=true&sslmode=require."
  pause
}

# ── 7 ────────────────────────────────────────────────────────────────────
s7() {
  stage "Storefront Supabase — seed, storage buckets, lock-down check"
  local ref; ref=$(ref_of "${NEXT_PUBLIC_SUPABASE_URL:-}")
  say "Seed = the CMS defaults (site settings, homepage copy, pricing) and one sample service package."
  if confirm "Seed storefront-$SHORT now? (answer N if you've seeded this project before)"; then
    run_cmd "npm run seed" env DATABASE_URL="${DIRECT_URL:-}" npm run seed --workspace=@repo/database
  fi
  printf '\n'
  say "Storage buckets:"
  open_url "https://supabase.com/dashboard/project/$ref/storage/buckets"
  step "New bucket 'images' — Public ON (book covers, banners)."
  step "New bucket 'ebooks' — Public OFF (private PDFs)."
  pause "Both created?"
  run_cmd "npm run harden-buckets (size and file-type limits)" \
    env NEXT_PUBLIC_SUPABASE_URL="${NEXT_PUBLIC_SUPABASE_URL:-}" SUPABASE_SERVICE_ROLE_KEY="${SUPABASE_SERVICE_ROLE_KEY:-}" \
    npm run harden-buckets --workspace=@repo/storage
  printf '\n'
  run_cmd "npm run check:data-api (every table must say blocked)" \
    env NEXT_PUBLIC_SUPABASE_URL="${NEXT_PUBLIC_SUPABASE_URL:-}" NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY="${NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY:-}" \
    npm run check:data-api --workspace=@repo/database
  if ! is_dev; then
    step "Project Settings → Database → Backups: confirm daily backups are on (Pro)."
  fi
  pause
}

# ── 8 ────────────────────────────────────────────────────────────────────
s8() {
  stage "Admin auth Supabase — create the project"
  say "Staff sign-in lives in its own project, so no customer sign-up can ever become a staff account."
  is_dev && note "Already have an admin auth project from development? Reuse it as dev — just copy its keys."
  open_url "https://supabase.com/dashboard/new"
  step "Name: admin-auth-$SHORT · same region · any strong DB password (the apps never use it). Free plan is fine."
  pause "Project ready?"
  open_url "https://supabase.com/dashboard/project/_/settings/api-keys"
  while :; do
    ask_url NEXT_PUBLIC_AUTH_SUPABASE_URL "Admin auth Project URL:"
    [[ "$NEXT_PUBLIC_AUTH_SUPABASE_URL" != "${NEXT_PUBLIC_SUPABASE_URL:-}" ]] && break
    warn "That's the storefront project's URL — admin refuses to boot with it. Copy the admin auth project's."
  done
  ask_req NEXT_PUBLIC_AUTH_SUPABASE_PUBLISHABLE_KEY "Publishable (or legacy anon) key:"
  ask_req AUTH_SUPABASE_SERVICE_ROLE_KEY "Secret / service_role key (hidden):" secret
  write_env NEXT_PUBLIC_AUTH_SUPABASE_PUBLISHABLE_KEY "$NEXT_PUBLIC_AUTH_SUPABASE_PUBLISHABLE_KEY"
  write_env AUTH_SUPABASE_SERVICE_ROLE_KEY "$AUTH_SUPABASE_SERVICE_ROLE_KEY"
  pause "Enter for the staff table SQL"
  _clear
  open_url "https://supabase.com/dashboard/project/$(ref_of "$NEXT_PUBLIC_AUTH_SUPABASE_URL")/sql/new"
  show_sql packages/database/prisma/sql/sync_staff.sql "Run this in the admin auth project's SQL editor (staff users table + sync trigger):"
  pause "Ran with no errors?"
}

# ── 9 ────────────────────────────────────────────────────────────────────
s9() {
  stage "Admin auth Supabase — lock sign-ups, add the Owner"
  local aref; aref=$(ref_of "${NEXT_PUBLIC_AUTH_SUPABASE_URL:-}")
  open_url "https://supabase.com/dashboard/project/$aref/auth/providers"
  step "Turn OFF 'Allow new users to sign up'."
  step "Google and any other provider: disable, unless you've set up a staff-only Google client."
  if ! is_dev; then
    step "Authentication settings: minimum password length 12, leaked-password protection on"
    step "  (if your plan has it), secure email change and secure password change on."
  fi
  pause "Done?"
  open_url "https://supabase.com/dashboard/project/$aref/auth/users"
  step "Add user → Create new user → the Owner's email + a strong temporary password → tick Auto Confirm User."
  ask_req OWNER_EMAIL "Owner's email:"
  write_env OWNER_EMAIL "$OWNER_EMAIL"
  open_url "https://supabase.com/dashboard/project/$aref/sql/new"
  step "Promote them in the SQL editor (expect '1 row affected'):"
  printf "\n      %supdate public.users set role = 'OWNER' where email = '%s';%s\n\n" "$BOLD" "$OWNER_EMAIL" "$RESET"
  pause "Row updated?"
}

# ── 10 ───────────────────────────────────────────────────────────────────
s10() {
  stage "Resend — sending domain and API key"
  if [[ -z "${DOMAIN:-}" ]]; then
    ask_req DOMAIN "Your domain, without www (e.g. example.in):"
    DOMAIN="${DOMAIN#https://}"; DOMAIN="${DOMAIN#www.}"; DOMAIN="${DOMAIN%/}"
    write_env DOMAIN "$DOMAIN"
  fi
  say "One verified domain serves both environments — skip to the key if $DOMAIN already shows Verified."
  open_url "https://resend.com/domains"
  step "Add domain → $DOMAIN → the region nearest India."
  step "Add the SPF / DKIM / MX records it lists to the domain's DNS (hPanel → Domains → DNS), then Verify."
  step "Also add a TXT record named _dmarc with value: v=DMARC1; p=none;"
  pause "Records added? (Verification can take a while — carry on.)"
  open_url "https://resend.com/api-keys"
  step "Create API key → name storefront-$SHORT → Sending access → domain $DOMAIN."
  ask_req RESEND_API_KEY "API key (re_…, hidden):" secret
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  local suggested="New School Book Press <orders@$DOMAIN>"
  ask EMAIL_FROM "From address (Enter = $suggested):"
  [[ -z "$EMAIL_FROM" ]] && EMAIL_FROM="$suggested"
  write_env EMAIL_FROM "$EMAIL_FROM"
  is_dev && warn "Dev sends real emails to whoever signs up there — test with your own addresses."
  pause
}

# ── 11 ───────────────────────────────────────────────────────────────────
s11() {
  stage "Storefront Supabase — sign-in emails and allowed addresses"
  local ref; ref=$(ref_of "${NEXT_PUBLIC_SUPABASE_URL:-}")
  say "Supabase's built-in mailer only reaches your own team, so customers would never get"
  say "confirmation or reset emails. Send them through Resend instead:"
  open_url "https://resend.com/api-keys"
  step "Create one more key: supabase-smtp-$SHORT (Sending access). Supabase is its only use."
  open_url "https://supabase.com/dashboard/project/$ref/auth/smtp"
  step "Enable custom SMTP: host smtp.resend.com · port 465 · username resend · password = that key"
  step "Sender email no-reply@$DOMAIN · sender name New School Book Press → Save."
  step "Emails → Templates: put the Press's name in Confirm sign-up, Reset password and Magic link."
  pause "Done?"
  open_url "https://supabase.com/dashboard/project/$ref/auth/url-configuration"
  step "Site URL: $NEXT_PUBLIC_STOREFRONT_URL"
  step "Redirect URLs: $NEXT_PUBLIC_STOREFRONT_URL/**"
  is_dev && step "  …and http://localhost:3000/** if you'll sign in locally against dev."
  step "Sign In / Providers → Email: Confirm email ON · minimum password length 8 ·"
  step "  leaked-password protection on, if your plan has it."
  step "Google or other providers: give each environment its own OAuth client with this project's callback URL."
  pause "Saved?"
}

# ── 12 ───────────────────────────────────────────────────────────────────
s12() {
  stage "Admin auth Supabase — password-reset emails and allowed addresses"
  local aref; aref=$(ref_of "${NEXT_PUBLIC_AUTH_SUPABASE_URL:-}")
  say "Staff invites go out through Resend from the app, but 'Forgot password' emails come"
  say "from this project — so it needs SMTP too."
  open_url "https://supabase.com/dashboard/project/$aref/auth/smtp"
  step "Same SMTP settings as stage 11 (a separate Resend key is tidier: supabase-smtp-admin-$SHORT)."
  step "Sender no-reply@$DOMAIN · sender name New School Book Press → Save."
  open_url "https://supabase.com/dashboard/project/$aref/auth/url-configuration"
  step "Site URL: $NEXT_PUBLIC_ADMIN_URL"
  step "Redirect URLs: exactly $NEXT_PUBLIC_ADMIN_URL/**"
  is_dev && step "  …and http://localhost:3001/** for local work against dev."
  pause "Saved?"
