# ── 13 ───────────────────────────────────────────────────────────────────
s13() {
  stage "Razorpay — keys and webhook"
  local mode=Test prefix=rzp_test_
  if ! is_dev; then
    mode=Live; prefix=rzp_live_
    say "Live keys need KYC and website activation (2–7 working days; the policy pages must be live)."
    if ! confirm "Is the account activated, and do you want live payments now?"; then
      warn "Leaving Razorpay unset — production takes Cash on Delivery only. Re-run --from 13 when live keys arrive, then --from 15."
      for k in RAZORPAY_KEY_ID RAZORPAY_KEY_SECRET; do printf -v "$k" '%s' ""; write_env "$k" ""; done
      SKIPPED+=("Razorpay live keys (re-run --from 13, then --from 15 and re-import on Hostinger)")
      pause; return
    fi
  fi
  open_url "https://dashboard.razorpay.com/app/keys"
  step "Switch the dashboard to $mode Mode (toggle at the top)."
  step "Account & Settings → API Keys → Generate key."
  ask_req RAZORPAY_KEY_ID "Key Id ($prefix…):"
  [[ "$RAZORPAY_KEY_ID" == "$prefix"* ]] || warn "Expected a key starting with $prefix — you may be in the wrong mode."
  write_env RAZORPAY_KEY_ID "$RAZORPAY_KEY_ID"
  ask_req RAZORPAY_KEY_SECRET "Key Secret (hidden):" secret
  write_env RAZORPAY_KEY_SECRET "$RAZORPAY_KEY_SECRET"
  pause "Enter for the webhook"
  _clear
  ensure_generated RAZORPAY_WEBHOOK_SECRET
  local hook="$NEXT_PUBLIC_STOREFRONT_URL/api/webhooks/razorpay"
  if is_dev && [[ -n "${VERCEL_AUTOMATION_BYPASS_SECRET_WEB:-}" ]]; then
    hook="$hook?x-vercel-protection-bypass=$VERCEL_AUTOMATION_BYPASS_SECRET_WEB"
  fi
  open_url "https://dashboard.razorpay.com/app/webhooks"
  step "Still in $mode Mode: Add New Webhook"
  step "  Webhook URL:   $hook"
  step "  Secret:        $RAZORPAY_WEBHOOK_SECRET"
  step "  Active events: payment.captured only → Create"
  if is_dev && [[ -n "${VERCEL_AUTOMATION_BYPASS_SECRET_WEB:-}" ]]; then
    note "  The ?x-vercel-protection-bypass part lets Razorpay past Vercel's login wall on dev."
  fi
  step "Account & Settings → Payment capture: Automatic (orders turn Paid only on payment.captured)."
  note "Test and live webhooks are separate lists in Razorpay — each environment's run adds its own."
  pause "Webhook created?"
}

# ── 14 ───────────────────────────────────────────────────────────────────
s14() {
  stage "Upstash Redis — rate limits (and production's data cache)"
  if is_dev; then
    say "Optional on dev: without it, rate limits only count per server instance. Enter skips both."
  else
    say "Required on Hostinger: it holds the storefront's data cache as well as the rate limits."
  fi
  open_url "https://console.upstash.com/redis"
  step "Create database → name storefront-$SHORT → region ap-south-1 (Mumbai)."
  step "Open it → REST API → copy UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN."
  if is_dev; then
    ask UPSTASH_REDIS_REST_URL "REST URL (Enter skips):"
    ask_secret UPSTASH_REDIS_REST_TOKEN "REST token (hidden, Enter skips):"
    UPSTASH_REDIS_REST_URL="${UPSTASH_REDIS_REST_URL%/}"
    write_env UPSTASH_REDIS_REST_URL "$UPSTASH_REDIS_REST_URL"
  else
    ask_url UPSTASH_REDIS_REST_URL "REST URL:"
    ask_req UPSTASH_REDIS_REST_TOKEN "REST token (hidden):" secret
    CACHE_STORE=redis; write_env CACHE_STORE redis
    CACHE_NAMESPACE=prod; write_env CACHE_NAMESPACE prod
    note "CACHE_STORE=redis and CACHE_NAMESPACE=prod go on both production sites."
  fi
  write_env UPSTASH_REDIS_REST_TOKEN "$UPSTASH_REDIS_REST_TOKEN"
