  printf '\n'
  printf '      %-18s %-24s %s\n' "" "storefront" "back office"
  printf '      %-18s %-24s %s\n' "Domain" "www.$DOMAIN" "admin.$DOMAIN"
  printf '      %-18s %-24s %s\n' "Branch" "main" "main"
