    set_secret WEB_ENV_FILE "$(cat "$WEB_OUT")"
    set_secret ADMIN_ENV_FILE "$(cat "$ADMIN_OUT")"
    [[ -n "${VERCEL_AUTOMATION_BYPASS_SECRET_WEB:-}" ]] && set_secret VERCEL_AUTOMATION_BYPASS_SECRET_WEB "$VERCEL_AUTOMATION_BYPASS_SECRET_WEB"
    [[ -n "${VERCEL_AUTOMATION_BYPASS_SECRET_ADMIN:-}" ]] && set_secret VERCEL_AUTOMATION_BYPASS_SECRET_ADMIN "$VERCEL_AUTOMATION_BYPASS_SECRET_ADMIN"
  else
    open_url "https://github.com/$REPO/settings/secrets/actions/new"
    step "Add four repository secrets:"
    step "  WEB_ENV_FILE   = the whole contents of $WEB_OUT"
    step "  ADMIN_ENV_FILE = the whole contents of $ADMIN_OUT"
    step "  VERCEL_AUTOMATION_BYPASS_SECRET_WEB / _ADMIN = the bypass secrets from stage 3"
    open_local "$WEB_OUT"
    open_local "$ADMIN_OUT"
  fi
  note "Optional, for the signed-in tests: E2E_CUSTOMER_EMAIL/_PASSWORD and E2E_STAFF_EMAIL/_PASSWORD (docs/testing.md)."
