s17() { if is_dev; then s17_dev; else s17_prod; fi; }

# ── 18 ───────────────────────────────────────────────────────────────────
s18() {
  stage "Check it works"
  if is_dev; then
    step "$NEXT_PUBLIC_STOREFRONT_URL/robots.txt says 'Disallow: /' (dev must never be indexed)."
  else
    step "$NEXT_PUBLIC_STOREFRONT_URL/robots.txt lists a Sitemap: line."
