# ── run ──────────────────────────────────────────────────────────────────
load_all
banner "Digital Storefront — $TARGET environment"
STAGES=(s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 s12 s13 s14 s15 s16 s17 s18)
for i in "${!STAGES[@]}"; do
  if (( i + 1 < FROM )); then _STAGE_INDEX=$((i + 1)); continue; fi
  "${STAGES[$i]}"
done

finish
if is_dev; then
  say "Next: bash docs/setup/environments.sh production"
else
  say "Next: the go-live steps in docs/production-launch.md (Phase 9)."
fi
say "How changes move from dev to production: docs/setup/environments.md"
